import { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../contexts/AuthContext';
import '../styles/RequestForm.css';

const RequestForm = ({ onCreated }) => {
  const { user } = useAuth();
  const [type, setType] = useState('event');
  const [responsibleId, setResponsibleId] = useState('');
  const [rooms, setRooms] = useState([]);
  const [employees, setEmployees] = useState([]);
  const [errors, setErrors] = useState({});
  const [formData, setFormData] = useState({
    // event
    date: '',
    startTime: '',
    endTime: '',
    room: '',
    needVideo: false,
    needSound: false,
    needProjector: false,
    extraInfo: '',
    // repair
    repairRoom: '',
    description: '',
    // video
    location: '',
    videoStartTime: '',
    videoEndTime: '',
    usageInfo: '',
  });

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [roomsRes, employeesRes] = await Promise.all([
          axios.get('/api/rooms'),
          axios.get('/api/admin/employees'),
        ]);
        setRooms(roomsRes.data);
        setEmployees(employeesRes.data);
      } catch (err) {
        console.error('Ошибка загрузки данных формы', err);
      }
    };
    fetchData();
  }, []);

  const handleChange = (e) => {
    const { name, value, type: inputType, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: inputType === 'checkbox' ? checked : value,
    }));
    if (errors[name]) setErrors(prev => ({ ...prev, [name]: undefined }));
  };

  const validate = () => {
    const newErrors = {};

    if (type === 'event') {
      if (!formData.date) newErrors.date = 'Дата обязательна';
      if (!formData.startTime) newErrors.startTime = 'Время начала обязательно';
      if (!formData.endTime) newErrors.endTime = 'Время окончания обязательно';
      if (!formData.room) newErrors.room = 'Выберите аудиторию';
      if (formData.startTime && formData.endTime && formData.startTime >= formData.endTime) {
        newErrors.endTime = 'Время окончания должно быть позже начала';
      }
      // Проверка, что дата и время не в прошлом
      if (formData.date && formData.startTime) {
        const eventDateTime = new Date(`${formData.date}T${formData.startTime}:00`);
        if (eventDateTime < new Date()) {
          newErrors.startTime = 'Дата и время не могут быть в прошлом';
          if (!newErrors.date) newErrors.date = 'Дата не может быть в прошлом';
        }
      }
    } else if (type === 'repair') {
      if (!formData.repairRoom) newErrors.repairRoom = 'Номер аудитории обязателен';
      if (!formData.description.trim()) newErrors.description = 'Опишите проблему';
    } else if (type === 'video') {
      if (!formData.location) newErrors.location = 'Место съёмки обязательно';
      if (!formData.videoStartTime) newErrors.videoStartTime = 'Время начала обязательно';
      if (!formData.videoEndTime) newErrors.videoEndTime = 'Время окончания обязательно';
      if (formData.videoStartTime && formData.videoEndTime && formData.videoStartTime >= formData.videoEndTime) {
        newErrors.videoEndTime = 'Время окончания должно быть позже начала';
      }
      // Проверка, что дата не в прошлом – у видеосъёмки нет отдельного поля date, но мы используем текущую дату?
      // По заданию у видеосъёмки нет даты, только время, значит проверяем только если у нас была бы дата. 
      // Но можно считать, что видеосъёмка планируется на сегодня? Обычно всё равно вводят дату в поле location? Нет, location это текст.
      // В задании не требуется дата для видеосъёмки, значит мы не можем проверить. Однако если мы добавим скрытую проверку на текущий день и время, то нужно поле даты. 
      // Оставим как есть, но добавим проверку, если бы дата была. Так как по требованиям даты нет, проверять на прошлое не будем для видео.
      // Если хотите, можно добавить поле даты для видеосъёмки в будущем.
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const buildDetails = () => {
    if (type === 'event') {
      return {
        date: formData.date,
        startTime: formData.startTime,
        endTime: formData.endTime,
        room: formData.room,
        needVideo: formData.needVideo,
        needSound: formData.needSound,
        needProjector: formData.needProjector,
        extraInfo: formData.extraInfo,
      };
    } else if (type === 'repair') {
      return {
        room: formData.repairRoom,
        description: formData.description,
      };
    } else {
      return {
        location: formData.location,
        startTime: formData.videoStartTime,
        endTime: formData.videoEndTime,
        usageInfo: formData.usageInfo,
      };
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    try {
      await axios.post('/api/requests', {
        type,
        responsibleId: responsibleId || null,
        details: buildDetails(),
      });
      onCreated();
    } catch (err) {
      alert('Ошибка создания заявки');
    }
  };

  return (
    <form className="request-form" onSubmit={handleSubmit}>
      <h2>Новая заявка</h2>

      <div className="form-group">
        <label>Тип заявки</label>
        <select value={type} onChange={(e) => setType(e.target.value)}>
          <option value="event">Мероприятие</option>
          <option value="repair">Ремонт</option>
          <option value="video">Видеосъёмка</option>
        </select>
      </div>

      <div className="form-group">
        <label>Ответственный (необязательно)</label>
        <select value={responsibleId} onChange={(e) => setResponsibleId(e.target.value)}>
          <option value="">Все сотрудники</option>
          {employees.map(emp => (
            <option key={emp.id} value={emp.id}>
              {emp.surname} {emp.name}
            </option>
          ))}
        </select>
      </div>

      {type === 'event' && (
        <>
          <div className="form-group">
            <label>Дата</label>
            <input type="date" name="date" value={formData.date} onChange={handleChange} />
            {errors.date && <span className="field-error">{errors.date}</span>}
          </div>
          <div className="form-row">
            <div className="form-group">
              <label>Начало</label>
              <input type="time" name="startTime" value={formData.startTime} onChange={handleChange} />
              {errors.startTime && <span className="field-error">{errors.startTime}</span>}
            </div>
            <div className="form-group">
              <label>Окончание</label>
              <input type="time" name="endTime" value={formData.endTime} onChange={handleChange} />
              {errors.endTime && <span className="field-error">{errors.endTime}</span>}
            </div>
          </div>
          <div className="form-group">
            <label>Аудитория</label>
            <select name="room" value={formData.room} onChange={handleChange}>
              <option value="">Выберите аудиторию</option>
              {rooms.map(r => <option key={r.id} value={r.number}>{r.number}</option>)}
            </select>
            {errors.room && <span className="field-error">{errors.room}</span>}
          </div>
          <div className="checkbox-group">
            <label><input type="checkbox" name="needVideo" checked={formData.needVideo} onChange={handleChange} /> Видеосъёмка</label>
            <label><input type="checkbox" name="needSound" checked={formData.needSound} onChange={handleChange} /> Звукооператор</label>
            <label><input type="checkbox" name="needProjector" checked={formData.needProjector} onChange={handleChange} /> Проектор</label>
          </div>
          <div className="form-group">
            <label>Дополнительная информация</label>
            <textarea name="extraInfo" value={formData.extraInfo} onChange={handleChange} rows="3" />
          </div>
        </>
      )}

      {type === 'repair' && (
        <>
          <div className="form-group">
            <label>Аудитория</label>
            <select name="repairRoom" value={formData.repairRoom} onChange={handleChange}>
              <option value="">Выберите аудиторию</option>
              {rooms.map(r => <option key={r.id} value={r.number}>{r.number}</option>)}
            </select>
            {errors.repairRoom && <span className="field-error">{errors.repairRoom}</span>}
          </div>
          <div className="form-group">
            <label>Описание проблемы</label>
            <textarea name="description" value={formData.description} onChange={handleChange} rows="4" />
            {errors.description && <span className="field-error">{errors.description}</span>}
          </div>
        </>
      )}

      {type === 'video' && (
        <>
          <div className="form-group">
            <label>Место съёмки</label>
            <input type="text" name="location" value={formData.location} onChange={handleChange} placeholder="Аудитория или адрес" />
            {errors.location && <span className="field-error">{errors.location}</span>}
          </div>
          <div className="form-row">
            <div className="form-group">
              <label>Начало</label>
              <input type="time" name="videoStartTime" value={formData.videoStartTime} onChange={handleChange} />
              {errors.videoStartTime && <span className="field-error">{errors.videoStartTime}</span>}
            </div>
            <div className="form-group">
              <label>Окончание</label>
              <input type="time" name="videoEndTime" value={formData.videoEndTime} onChange={handleChange} />
              {errors.videoEndTime && <span className="field-error">{errors.videoEndTime}</span>}
            </div>
          </div>
          <div className="form-group">
            <label>Использование материала</label>
            <textarea name="usageInfo" value={formData.usageInfo} onChange={handleChange} rows="3" />
            {errors.usageInfo && <span className="field-error">{errors.usageInfo}</span>}
          </div>
        </>
      )}

      <div className="form-actions">
        <button type="submit" className="submit-btn">Отправить</button>
        <button type="button" className="cancel-btn" onClick={() => onCreated()}>Отмена</button>
      </div>
    </form>
  );
};

export default RequestForm;
